  function pvpRespawnPoint(playerId){const ids=['host',...GUEST_IDS],index=Math.max(0,ids.indexOf(playerId));return world.spawnPoints?.[index]||world.spawn||PLAYER_SPAWNS[playerId]||{x:0,z:0};}
